CatalogChain:                snapshotCatalogChain,
// LatestBuildBlocks controls how often latest-dataset snapshots
// (accounts, KV, commitment-branch, etc.) are rebuilt; all latest
// datasets share this single coarse cadence. Operators may tune it.
LatestBuildBlocks:            statesnapshots.DefaultLatestBuildBlocks,
DeferLatestBuildWhileSyncing: true,
// Periodic sync-time rotation is disabled until immutable-base point
// reads and full-base rewrite amortization meet the replay release gate.
// A 40k-block cadence can otherwise continuously rewrite a large base.
DeferHistoryBuildWhileSyncing: shouldDeferColdSnapshotHistoryWhileSyncing(chainConfig),
MaxDeferredHistoryBlocks:      maxDeferredHistoryBlocks,

// elapse between production latest-snapshot builds. 0 disables the latest
// build pass entirely. Latest builds are full-keyspace scans, so all latest
// datasets share this single coarse cadence rather than rebuilding every tick.
LatestBuildBlocks uint64
// DeferLatestBuildWhileSyncing prevents the full-keyspace latest snapshot
// scan from competing with an active historical sync session. The regular
// lifecycle/sync-complete wake builds it once the importer is idle.
DeferLatestBuildWhileSyncing bool
// DeferHistoryBuildWhileSyncing prevents state-history compression and its
// mandatory history accessors from competing with a node that is farther
// behind than HistoryWindow while the cold backlog remains below
// MaxDeferredHistoryBlocks. The ordered lifecycle drains the bounded backlog
// immediately once sync enters the recent hot window.

if r == nil || !r.cfg.Enabled || r.cfg.LatestBuildBlocks == 0 {
	return false, false, nil
}
if ctx == nil {
	ctx = context.Background()
}
if err = ctx.Err(); err != nil {
	return
}
if r.pendingLatest != nil {
	return r.publishPreparedLatest(ctx)
}
if r.cfg.DeferLatestBuildWhileSyncing && r.syncActive() {
	return false, true, nil
}
block, _, ok, err := r.latestBuildWatermark()
if err != nil || !ok {
	return false, false, err
}
prev := r.lastLatestBuildBlock.Load()
